 for(let Yh=0;Yh<=H+1e-6;Yh+=.3){const a=back(PN,Yh);mesh.moveTo(a[0],a[1]);for(let Z=PN+.3;Z<=PF+1e-6;Z+=.3){const b=back(Z,Yh);mesh.lineTo(b[0],b[1]);}}
