const C2={w:A(1,'Watch'),wd:A(1,'winger'),gp:A(1,'Gordillo pins'),sl:A(1,'slips'),bp:A(1,'back post'),pc:A(1,'pass comes'),ft:A(1,'first time'),gl:A(1,'Goal'),end:AUTH[1].seconds};
